type Timer struct {
	C         <-chan Time
	initTimer bool
}

func NewTimer(d Duration) *Timer {
	c := make(chan Time, 1)
	t := (*Timer)(newTimer(when(d), 0, sendTime, c, syncTimer(c)))
	t.C = c
	return t
}

func main() {
	t := time.NewTimer(2 * time.Second)
	fmt.Println("<-t.C", <-t.C)

	fmt.Println("2s结束了")
}

// AfterFunc waits for the duration to elapse and then calls f
// in its own goroutine. It returns a [Timer] that can
// be used to cancel the call using its Stop method.
// The returned Timer's C field is not used and will be nil.
func AfterFunc(d Duration, f func()) *Timer {
	return (*Timer)(newTimer(when(d), 0, goFunc, f, nil))
}

func TestAfterFunc() {
	t := time.AfterFunc(1*time.Second, func() {
		fmt.Println("time.AfterFunc在1秒后被触发了")
	})

	fmt.Println("<-t.C", <-t.C)
}

func TestAfter() {
	ch := time.After(1 * time.Second)
	fmt.Println("<ch", <-ch)
}

func After(d Duration) <-chan Time {
	return NewTimer(d).C
}

select {
   case val := <-ch:
      fmt.Printf("val is %s\n", val)
   case <-time.After(time.Second * 2):
      fmt.Println("timeout!!!")
   }

type Ticker struct {
   C <-chan Time // The channel on which the ticks are delivered.
   r runtimeTimer
}

func TestTicker(sem <-chan struct{}) {
	t := time.NewTicker(1 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-t.C:
			fmt.Println("轮询")
		case <-sem:
			fmt.Println("结束Ticker")
			return
		}
	}
}

func main() {
	// 创建一个退出信号，要退出时往里面写值
	sem := make(chan struct{}, 1)
	go TestTicker(sem)
	// 5s后退出轮询
	time.AfterFunc(5*time.Second, func() {
		sem <- struct{}{}
	})
	for {
	}
}
